    Style modifyCellStyle(Style cellStyle, Object value);

    /**
     * 对当前形态中涉及到的单元格值进行预处理
     *
     * @param value      值
     * @param calculator 算子
     */
    void valuePretreatment(Object value, CalculatorProvider calculator);

}

