 * 自定义预览方式接口
 */
public interface PreviewProvider extends Mutable, Filter {

    String MARK_STRING = "PreviewProvider";

    int CURRENT_LEVEL = 1;


    /**
     * 下拉弹出菜单的名字
     * @return 弹出菜单名字
     */
