接口作用
更新生命周期插件接入点，方法返回值为boolean
true: 不执行对应操作，如onLoad返回true，则不执行默认load操作。
false：继续执行对应默认操作
接口内容
主要接口
/**
 * 更新生命周期插件接入点
 * 方法返回值为boolean
 * true: 不执行对应操作，如onLoad返回true，则不执行load操作。
 * false：继续执行对应操作
 *
 * @author James.Zhao
 * @version 5.1.3
 * Created by James.Zhao on 2020/4/8
 */
public interface UpdateLoadProvider extends Mutable {

    String XML_TAG = "UpdateLoadProvider";

    int CURRENT_LEVEL = 1;

    /**
     * 更新生命周期开始前
     */
     boolean onStart(TaskInfoBO bo, AbstractLoad load);

    /**
     * 数据加载与更新之前
     */
     boolean onLoad(TaskInfoBO bo, AbstractLoad load);

    /**
     * 数据提交之前
     */
     boolean onCommit(TaskInfoBO bo, AbstractLoad load);

    /**
     * 数据表重命名前
     */
     boolean onRename(TaskInfoBO bo, AbstractLoad load);

    /**
     * 更新生命周期正常结束后调用
     */
     boolean onEnd(TaskInfoBO bo, AbstractLoad load);

    /**
     * 数据表回滚前
     */
     boolean onRollback(TaskInfoBO bo, AbstractLoad load, Throwable throwable);
}

接口接入




提供给插件的抽象类
/**
 * 更新生命周期扩展点抽象类
