    }

    @Override
    public String mark4Provider() {
        return getClass().getName();
    }

    @Override
    public  boolean onLoad(TaskInfoBO bo, AbstractLoad load) {
        return false;
    }

    @Override
    public  boolean onCommit(TaskInfoBO bo, AbstractLoad load) {
        return false;
    }

    @Override
    public  boolean onRename(TaskInfoBO bo, AbstractLoad load) {
        return false;
    }

    @Override
    public  boolean onEnd(TaskInfoBO bo, AbstractLoad load) {
        return false;
    }

    @Override
