请求前钩子


reqAfterSuccess
reqAfterSuccess(fn: (res: any) => void)
请求成功钩子


reqAfterComplete
reqAfterComplete(fn: (res: any) => void)
请求完成钩子


reqAfterFail
reqAfterFail(fn: (res: any) => void)
请求失败钩子



BI.config('bi.provider.base.req', (provider) => {
    provider.reqBefore((options) => {
        console.log('请求前');
        return options;
    });
