Beginner Tutorial - ConfigurationIntroductionStore into FineDBBasic TypeData Model with Conf MemberCollection of Basic TypeCollection of Data ModelMap of Basic TypeMap of Data ModelExampleConfiguration ClassSave the configurationBeginner Tutorial - Configuration
Introduction
Having a place to store custom configuration is a better choice than creating a table every time, especially when the custom data is limited. In this tutorial, we will learn how to store configuration into FineDB.
Store into FineDB
All the configuration data are stored in the FINE_CONF_ENTITY table of FineDB, such as the data connection config.
In order to store custom data, we need to wrap our object by com.fr.config.holder.Conf, and pass actual data type by generics. FineReport has provided a factory class com.fr.config.holder.factory.Holders to construct the instance.
package com.fr.config.holder.factory;

import com.fr.config.holder.Conf;
import com.fr.config.holder.impl.ColConf;
import com.fr.config.holder.impl.MapConf;
import com.fr.config.holder.impl.ObjConf;
import com.fr.config.holder.impl.ObjectColConf;
import com.fr.config.holder.impl.ObjectMapConf;
import com.fr.config.holder.impl.SimConf;

import java.util.Collection;
import java.util.Map;

/**
 * Factory class of the wrapper
 */
public class Holders {
    /**
     * Create a Holder for basic types. It should be used as long as T does not contain a ConfigHolder field
     *
     * @param property
     * @param t
     * @param nameSpace
     * @param       
     * @return
     * @see Holders#simple(Object)
     */
    @Deprecated
    public static  Conf simple(String property, T t, String nameSpace) {
        return new SimConf(property, t).setNameSpace(nameSpace);
    }

    public static  Conf simple(T t) {
        return new SimConf(t);
    }

    /**
     * Create a Holder for T class. T contains a ConfigHolder field.
     *
     * @param property
     * @param t
     * @param type
     * @param nameSpace
     * @param 
     * @return
     * @see Holders#obj(Object, Class)
     */
    @Deprecated
    public static  Conf obj(String property, T t, Class type, String nameSpace) {
        return new ObjConf(property, t, type).setNameSpace(nameSpace);
    }

    public static  Conf obj(T t, Class type) {
        return new ObjConf(t, type);
    }


    /**
     * Create a Holder for the collection of basic data types.
     *
     * @param property
     * @param collection
     * @param valueType
     * @param nameSpace
     * @param 
     * @return
     * @see Holders#objCollection(Collection, Class)
     */
    @Deprecated
    @SuppressWarnings("unchecked")
    public static  Conf> collection(String property, Collection collection, Class valueType, String nameSpace) {
        return new ColConf(property, collection, valueType).setNameSpace(nameSpace);
    }

    @SuppressWarnings("unchecked")
    public static  ColConf> collection(Collection collection, Class valueType) {
        return new ColConf(collection, valueType);
    }

    /**
     * Create a Holder for the collection of T class.
     *
     * @param property   属性标签
     * @param collection
     * @param type
     * @param nameSpace  名字空间
     * @param 
     * @return 属性节点的包装
     * @see Holders#collection(Collection, Class)
     */
    @Deprecated
    public static  ObjectColConf> objCollection(String property, Collection collection, Class type, String nameSpace) {
        return new ObjectColConf>(property, collection, type).setNameSpace(nameSpace);
    }

    public static  ObjectColConf> objCollection(Collection collection, Class type) {
        return new ObjectColConf>(collection, type);
    }

    public static  ObjectColConf> objCollection(Collection collection, Class type, boolean order) {
        return new ObjectColConf>(collection, type, order);
    }

    /**
     * Create a Holder for the Map which key and value are of basic type.
     *
     * @param property
     * @param map
     * @param keyType   not null
     * @param valueType not null
     * @param nameSpace
     * @param 
     * @param 
     * @return
     * @see Holders#map(Map, Class, Class)
     */
    @Deprecated
    @SuppressWarnings("unchecked")
    public static  MapConf> map(String property, Map map, Class keyType, Class valueType, String nameSpace) {
        return new MapConf(property, map, keyType, valueType).setNameSpace(nameSpace);
    }

    @SuppressWarnings("unchecked")
    public static  MapConf> map(Map map, Class keyType, Class valueType) {
        return new MapConf(map, keyType, valueType);
    }

    /**
     * Value is a Holder for the Map of V class. V contains a ConfigHolder field.
     * KeyType can be empty, but the key in the map has to be basic type or String. ValueType can be empty, but it has to be complex type.
     *
     * @param property
     * @param map
     * @param keyType
     * @param valueType
     * @param nameSpace
     * @param 
     * @param 
     * @return
     * @see Holders#objMap(Map, Class, Class)
     */
    @Deprecated
    public static  ObjectMapConf> objMap(String property, Map map, Class keyType, Class valueType, String nameSpace) {
        return new ObjectMapConf>(property, map, keyType, valueType).setNameSpace(nameSpace);
    }

    public static  ObjectMapConf> objMap(Map map, Class keyType, Class valueType) {
        return new ObjectMapConf>(map, keyType, valueType);
    }

    public static  ObjectMapConf> objMap(Map map, Class keyType, Class valueType, boolean ordered) {
        return new ObjectMapConf>(map, keyType, valueType, ordered);
    }
}

Basic Type
Use Holders.simple() to create such configuration, Including basic types and String.
private Conf demoString = Holders.simple(StringUtils.EMPTY);

public String getDemoString(){
    return demoString.get();
}

public void setDemoString(String s){
    demoString.set(s);
}

Data Model with Conf Member
If we define a data model, which member value also needs to be stored, we should wrap the member with Conf. In addition, the data model has to be created by Holders.obj().
package com.fr.plugin.configfile;

import com.fr.config.holder.Conf;
import com.fr.config.holder.factory.Holders;
